                g = sys.modules["__main__"].__dict__
                snap = {k: canon(v) for k, v in g.items() if not k.startswith("_")}
                with open(f"/run/sbx/state/repl-{os.getpid()}.json", "w") as f:
                    json.dump(snap, f, sort_keys=True)
            except Exception:
                pass
            return ">>> "

    sys.ps1 = Prompt()


